import unittest
from solution import collapse_intervals

class T(unittest.TestCase):
    def test_overlap(self):
        self.assertEqual(collapse_intervals([[1, 3], [2, 6]]), [[1, 6]])
    def test_touch(self):
        self.assertEqual(collapse_intervals([[1, 3], [3, 5]]), [[1, 5]])
    def test_nested(self):
        self.assertEqual(collapse_intervals([[1, 10], [2, 3]]), [[1, 10]])
    def test_unsorted(self):
        self.assertEqual(collapse_intervals([[5, 6], [1, 2], [2, 3]]), [[1, 3], [5, 6]])
    def test_single(self):
        self.assertEqual(collapse_intervals([[1, 2]]), [[1, 2]])
    def test_negative(self):
        self.assertEqual(collapse_intervals([[-5, -1], [-3, 0]]), [[-5, 0]])
